/* this is a recreation of twitter search in css */
.form {
  --input-text-color: #fff;
  --input-bg-color: #283542;
  --focus-input-bg-color: transparent;
  --text-color: #949faa;
  --active-color: #1b9bee;
  --width-of-input: 200px;
  --inline-padding-of-input: 1.2em;
  --gap: 0.9rem;
}
/* form style */
.form {
  font-size: 0.9rem;
  display: flex;
  gap: 0.5rem;
  align-items: center;
  width: var(--width-of-input);
  position: relative;
  isolation: isolate;
}
/* a fancy bg for showing background and border when focus. */
.fancy-bg {
  position: absolute;
  width: 100%;
  inset: 0;
  background: var(--input-bg-color);
  border-radius: 30px;
  height: 100%;
  z-index: -1;
  pointer-events: none;
  box-shadow: rgba(0, 0, 0, 0.16) 0px 1px 4px;
}
/* label styling */
label {
  width: 100%;
  padding: 0.8em;
  height: 40px;
  padding-inline: var(--inline-padding-of-input);
  display: flex;
  align-items: center;
}

.search,.close-btn {
  position: absolute;
}
/* styling search-icon */
.search {
  fill: var(--text-color);
  left: var(--inline-padding-of-input);
}
/* svg -- size */
svg {
  width: 17px;
  display: block;
}
/* styling of close button */
.close-btn {
  border: none;
  right: var(--inline-padding-of-input);
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  padding: 0.1em;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--active-color);
  opacity: 0;
  visibility: hidden;
}
/* styling of input */
.input {
  color: var(--input-text-color);
  width: 100%;
  margin-inline: min(2em,calc(var(--inline-padding-of-input) + var(--gap)));
  background: none;
  border: none;
}

.input:focus {
  outline: none;
}

.input::placeholder {
  color: var(--text-color)
}
/* input background change in focus */
.input:focus ~ .fancy-bg {
  border: 1px solid var(--active-color);
  background: var(--focus-input-bg-color);
}
/* search icon color change in focus */
.input:focus ~ .search {
  fill: var(--active-color);
}
/* showing close button when typing */
.input:valid ~ .close-btn {
  opacity: 1;
  visibility: visible;
}
/* this is for the default background in input,when selecting autofill options -- you can remove this code if you do not want to override the browser style.  */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
input:-webkit-autofill:active {
  -webkit-transition: "color 9999s ease-out, background-color 9999s ease-out";
  -webkit-transition-delay: 9999s;
}

.win98-container {
  width: 30rem;
  margin: 2rem auto;
  font-family: "Tahoma", "Pixelated MS Sans Serif", sans-serif;
  position: relative;
  isolation: isolate;
  --win98-blue: #0a246a;
  --win98-light: #c0c0c0;
  --win98-dark: #808080;
  --win98-white: #ffffff;
  --win98-black: #000000;
}

.win98-window {
  background: var(--win98-light);
  border: 2px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  position: relative;
  z-index: 10;
  transition: all 0.3s ease;
}

.win98-titlebar {
  background: linear-gradient(to right, var(--win98-blue), #0a248a);
  color: white;
  padding: 3px 2px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid var(--win98-dark);
  position: relative;
  z-index: 20;
}

.win98-title {
  font-size: 0.8rem;
  font-weight: bold;
  margin-left: 2px;
  letter-spacing: 0.5px;
}

.win98-controls {
  display: flex;
  gap: 2px;
  margin-right: 2px;
}

.win98-button {
  width: 16px;
  height: 14px;
  background: var(--win98-light);
  border: 1px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: bold;
  cursor: pointer;
  user-select: none;
}

.win98-button:active {
  border-color: var(--win98-dark) var(--win98-white) var(--win98-white)
    var(--win98-dark);
  padding: 1px 0 0 1px;
}

.win98-content {
  padding: 8px;
}

.win98-menu-bar {
  display: flex;
  gap: 15px;
  margin-bottom: 10px;
  padding: 2px 5px;
  background: var(--win98-light);
  border: 1px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
}

.win98-menu-item {
  font-size: 0.8rem;
  cursor: pointer;
  padding: 1px 3px;
}

.win98-menu-item:hover {
  background: var(--win98-blue);
  color: white;
}

.win98-input-frame {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 15px;
}

.win98-input-label {
  font-size: 0.8rem;
  font-weight: bold;
  min-width: 40px;
}

.win98-input {
  flex: 1;
  height: 22px;
  background: white;
  border: 2px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  font-family: "Tahoma", sans-serif;
  font-size: 0.8rem;
  padding: 0 3px;
  outline: none;
}

.win98-input:focus {
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  background: #ffffe0;
}

.win98-status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: var(--win98-dark);
  color: white;
  padding: 2px 5px;
  font-size: 0.7rem;
  border-top: 1px solid var(--win98-white);
  min-height: 18px;
}

.win98-status-indicators {
  display: flex;
  gap: 5px;
}

.win98-indicator {
  background: var(--win98-white);
  color: var(--win98-black);
  padding: 0 3px;
  border: 1px solid;
  border-color: var(--win98-white) var(--win98-dark) var(--win98-dark)
    var(--win98-white);
  font-weight: bold;
}

.win98-resize-handle {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 15px;
  height: 15px;
  background: linear-gradient(
    135deg,
    transparent 0%,
    transparent 50%,
    var(--win98-dark) 50%,
    var(--win98-dark) 60%,
    transparent 60%
  );
  cursor: nw-resize;
}

.secret-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(
    circle at center,
    rgba(0, 255, 255, 0.1) 0%,
    transparent 70%
  );
  opacity: 0;
  transition: all 0.8s ease;
  z-index: 5;
  pointer-events: none;
}

.matrix-rain {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: linear-gradient(
    0deg,
    transparent 0%,
    rgba(0, 255, 0, 0.1) 2%,
    transparent 4%
  );
  background-size: 100% 30px;
  opacity: 0;
  z-index: 6;
  pointer-events: none;
  animation: matrix-fall 2s linear infinite;
}

.glitch-effect {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  z-index: 7;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.hologram-projection {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  border: 2px solid rgba(0, 255, 255, 0.5);
  border-radius: 0;
  opacity: 0;
  z-index: 4;
  pointer-events: none;
  box-shadow: 0 0 30px rgba(0, 255, 255, 0.3);
}

.win98-container:hover .win98-window {
  transform: translateY(-1px);
}

.win98-container:hover .win98-button {
  background: #d0d0d0;
}

.win98-container:hover .secret-overlay {
  opacity: 0.2;
}

.win98-container:focus-within .win98-window {
  background: linear-gradient(145deg, #1a1a2a, #0a0a1a);
  border: 2px solid #00ffff;
  transform: perspective(1000px) rotateX(3deg) translateY(-5px);
  position: relative;
  z-index: 100;
}

.win98-container:focus-within .win98-titlebar {
  background: linear-gradient(to right, #001122, #003344);
  border-bottom: 1px solid #00ffff;
  animation: title-glow 2s ease-in-out infinite alternate;
}

.win98-container:focus-within .win98-title {
  color: #00ffff;
  text-shadow: 0 0 10px rgba(0, 255, 255, 0.8);
  animation: text-flicker 3s ease-in-out infinite;
}

.win98-container:focus-within .win98-button {
  background: linear-gradient(145deg, #2a2a3a, #1a1a2a);
  border: 1px solid #00ffff;
  color: #00ffff;
  box-shadow: 0 0 10px rgba(0, 255, 255, 0.3);
}

.win98-container:focus-within .win98-content {
  background: rgba(10, 10, 20, 0.8);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}

.win98-container:focus-within .win98-menu-bar {
  background: linear-gradient(90deg, #1a1a2a, #2a2a3a);
  border: 1px solid #00ffff;
}

.win98-container:focus-within .win98-menu-item {
  color: #00ffff;
  text-shadow: 0 0 5px rgba(0, 255, 255, 0.5);
}

.win98-container:focus-within .win98-menu-item:hover {
  background: linear-gradient(90deg, #00ffff, #0088ff);
  color: #000;
  text-shadow: none;
}

.win98-container:focus-within .win98-input-frame {
  border: 1px solid rgba(0, 255, 255, 0.2);
  padding: 8px;
  border-radius: 2px;
  background: rgba(20, 20, 30, 0.3);
}

.win98-container:focus-within .win98-input-label {
  color: #00ffff;
  text-shadow: 0 0 8px rgba(0, 255, 255, 0.6);
}

.win98-container:focus-within .win98-input {
  background: linear-gradient(145deg, #000011, #000022);
  border: 2px solid #00ffff;
  color: #00ffff;
  box-shadow:
    inset 0 0 15px rgba(0, 0, 0, 0.8),
    0 0 10px rgba(0, 255, 255, 0.2);
  text-shadow: 0 0 8px rgba(0, 255, 255, 0.5);
}

.win98-container:focus-within .win98-input::placeholder {
  color: #4488aa;
  font-style: italic;
}

.win98-container:focus-within .win98-status-bar {
  background: linear-gradient(90deg, #0a1a2a, #0a2a3a);
  border-top: 1px solid #00ffff;
  color: #00ffff;
  text-shadow: 0 0 5px rgba(0, 255, 255, 0.5);
}

.win98-container:focus-within .win98-indicator {
  background: linear-gradient(145deg, #00ffff, #0088ff);
  color: #000;
  border: 1px solid #00ffff;
  box-shadow: 0 0 8px rgba(0, 255, 255, 0.3);
}

.win98-container:focus-within .win98-resize-handle {
  background: linear-gradient(
    135deg,
    transparent 0%,
    transparent 50%,
    #00ffff 50%,
    #00ffff 60%,
    transparent 60%
  );
  box-shadow: 0 0 10px #00ffff;
}

.win98-container:focus-within .secret-overlay {
  opacity: 0.6;
  animation: overlay-pulse 4s ease-in-out infinite;
}

.win98-container:focus-within .matrix-rain {
  opacity: 0.4;
  animation: matrix-fall 0.5s linear infinite;
}

.win98-container:focus-within .glitch-effect {
  opacity: 0.5;
  animation: glitch-subtle 0.3s ease-in-out infinite alternate;
}

.win98-container:focus-within .hologram-projection {
  opacity: 0.7;
  animation: projection-pulse 3s ease-in-out infinite;
}

/* Animations */
@keyframes title-glow {
  0% {
    box-shadow: 0 0 8px rgba(0, 255, 255, 0.4);
  }
  100% {
    box-shadow: 0 0 20px rgba(0, 255, 255, 0.7);
  }
}

@keyframes text-flicker {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.9;
  }
}

@keyframes matrix-fall {
  0% {
    background-position: 0 0;
  }
  100% {
    background-position: 0 30px;
  }
}

@keyframes overlay-pulse {
  0%,
  100% {
    opacity: 0.4;
    transform: scale(1);
  }
  50% {
    opacity: 0.7;
    transform: scale(1.01);
  }
}

@keyframes glitch-subtle {
  0% {
    transform: translate(0);
    opacity: 0.5;
  }
  20% {
    transform: translate(-1px, 1px);
    opacity: 0.7;
  }
  40% {
    transform: translate(1px, -1px);
    opacity: 0.5;
  }
  60% {
    transform: translate(-0.5px, 0.5px);
    opacity: 0.6;
  }
  80% {
    transform: translate(0.5px, -0.5px);
    opacity: 0.7;
  }
  100% {
    transform: translate(0);
    opacity: 0.5;
  }
}

@keyframes projection-pulse {
  0%,
  100% {
    opacity: 0.5;
    box-shadow: 0 0 15px rgba(0, 255, 255, 0.2);
  }
  50% {
    opacity: 0.8;
    box-shadow: 0 0 30px rgba(0, 255, 255, 0.4);
  }
}

